// Throwaway native-GPU diagnosis. Frozen production inputs; no application edits.
import { Color, FloatType, GLSL3, Mesh, NoBlending, OrthographicCamera, PlaneGeometry, ShaderMaterial, UniformsUtils, WebGLRenderTarget } from 'three'
import { getInitializedSimulationRuntime } from '/src/ui/runtime/simulationRuntime'
import { Tokens } from '/src/core/providers/tokens'
import { GpuTimer } from '/tests/browser/gpuTimer'
import { state } from './profile.browser'
import { RingDustRaymarchMaterial as BaselineMaterial } from './baseline-RingDustRaymarchMaterial'
import { createDustClumpGradientTexture } from '/src/core/renderables/DetailedRingStreamingSystem/dust/DustClumpNoise'

const stats = (xs: number[]) => {
  const sorted = xs.slice().sort((a, b) => a - b)
  return { count: xs.length, p50: sorted[Math.ceil(xs.length * .5) - 1], p95: sorted[Math.ceil(xs.length * .95) - 1], max: sorted.at(-1) }
}
const owner = (o: any, id: number) => {
  for (; o; o = o.parent) if (o.model?.getAttribute('id') === id) return true
  return false
}
export async function diagnose(actorId: number) {
  const container = getInitializedSimulationRuntime()!.container
  const engine: any = container.get(Tokens.Engine), renderer = container.get(Tokens.Renderer)
  const volume: any = container.get(Tokens.DepthVolumeRegistry).volumes().find(v => owner(v, actorId) && v.material.uniforms.uDustMaxSteps)
  if (!volume) throw new Error(`Dust ${actorId} missing`)
  engine.stop()
  const gl = renderer.getContext() as WebGL2RenderingContext
  const savedTarget = renderer.getRenderTarget(), savedAlpha = renderer.getClearAlpha()
  const savedColor = renderer.getClearColor(new Color()), savedAuto = renderer.autoClear
  const targets: WebGLRenderTarget[] = [], materials: ShaderMaterial[] = []
  const draw = renderer.render
  const blitMaterial = new ShaderMaterial({ glslVersion: GLSL3, uniforms: { map: { value: null } }, depthTest: false, depthWrite: false, blending: NoBlending,
    vertexShader: 'void main(){gl_Position=vec4(position.xy,0.0,1.0);}',
    fragmentShader: 'precision highp float; uniform sampler2D map; out vec4 fragColor; void main(){fragColor=texelFetch(map,ivec2(gl_FragCoord.xy),0);}' })
  const blit = new Mesh(new PlaneGeometry(2, 2), blitMaterial), blitCamera = new OrthographicCamera()
  let mesh: Mesh, camera: any, uniforms: any, width = 0, height = 0
  const source = volume.material.fragmentShader
  const baselineOwner = new BaselineMaterial(undefined, { clumps: true, phaseHG: true, arcs: true, lightAtOrigin: true, extinction: true })
  const make = (fragmentShader: string, removeDefine?: string) => {
    const defines = { ...volume.material.defines }
    if (removeDefine) delete defines[removeDefine]
    const m = new ShaderMaterial({ vertexShader: volume.material.vertexShader, fragmentShader, uniforms, defines,
      side: volume.material.side, depthTest: false, depthWrite: false, blending: NoBlending })
    materials.push(m); return m
  }
  const read = (target: WebGLRenderTarget) => {
    const pixels = new Float32Array(target.width * target.height * 4)
    renderer.readRenderTargetPixels(target, 0, 0, target.width, target.height, pixels)
    if (pixels.some(x => !Number.isFinite(x))) throw new Error('Nonfinite dust image')
    return pixels
  }
  try {
    renderer.autoClear = false
    renderer.render = function (object: any, view: any) {
      draw.call(this, object, view)
      if (object !== volume || uniforms) return
      uniforms = {}
      for (const [name, u] of Object.entries(object.material.uniforms) as any) uniforms[name] = u.value?.isTexture ? { value: u.value } : UniformsUtils.clone({ u }).u
      const depth = object.material.uniforms.uSceneDepth.value
      const copy = new WebGLRenderTarget(depth.image.width, depth.image.height, { type: FloatType, depthBuffer: false, minFilter: depth.minFilter, magFilter: depth.magFilter })
      targets.push(copy)
      const previous = renderer.getRenderTarget()
      renderer.setRenderTarget(copy); blitMaterial.uniforms.map.value = depth
      draw.call(renderer, blit, blitCamera); renderer.setRenderTarget(previous)
      uniforms.uSceneDepth.value = copy.texture
      width = uniforms.uResolution.value.x; height = uniforms.uResolution.value.y
      camera = view.clone(); mesh = new Mesh(object.geometry, blitMaterial)
      mesh.layers.mask = object.layers.mask; mesh.matrixAutoUpdate = false
      mesh.matrix.copy(object.matrixWorld); mesh.updateMatrixWorld(true); mesh.frustumCulled = false
    }
    engine.renderFrame(); renderer.render = draw
    if (!uniforms) throw new Error('Dust capture failed')
    const snapshot = state()
    const values: any = {}
    for (const [name, u] of Object.entries(uniforms) as any) values[name] = u.value?.isTexture
      ? { texture: true, width: u.value.image.width, height: u.value.image.height, minFilter: u.value.minFilter, generateMipmaps: u.value.generateMipmaps }
      : u.value?.toArray ? u.value.toArray() : u.value
    const output = new WebGLRenderTarget(width, height, { type: FloatType, depthBuffer: false }); targets.push(output)
    const render = (m: ShaderMaterial) => {
      renderer.setRenderTarget(output); renderer.setClearColor(0, 0); renderer.clear(true, false, false)
      mesh.material = m; draw.call(renderer, mesh, camera)
    }
    const measure = async (m: ShaderMaterial) => {
      const timer = new GpuTimer(gl), samples: number[] = []
      try {
        for (let i = 0; i < 6; i++) { render(m); await new Promise(r => setTimeout(r, 0)) }
        for (let i = 0; i < 32; i++) { timer.measure(() => render(m)); await new Promise(r => setTimeout(r, 0)); samples.push(...timer.poll()) }
        const deadline = performance.now() + 30000
        while (timer.pendingCount) { await new Promise(r => setTimeout(r, 16)); samples.push(...timer.poll()); if (performance.now() > deadline) throw new Error('Dust timer timeout') }
        return { summary: stats(samples), samples }
      } finally { timer.dispose() }
    }
    const baseline = make(baselineOwner.fragmentShader)
    const candidate = make(source)
    const creationMs: number[] = []
    for (let i = 0; i < 12; i++) {
      const start = performance.now(), texture = createDustClumpGradientTexture()
      creationMs.push(performance.now() - start); texture.dispose()
    }
    render(baseline); const reference = read(output)
    const compare = (candidate: Float32Array) => {
      let maxError = 0, error = 0, signal = 0, different = 0, alphaPixels = 0
      for (let i = 0; i < reference.length; i++) { const d = Math.abs(reference[i] - candidate[i]); maxError = Math.max(maxError, d); error += d; signal += Math.abs(reference[i]); if (d !== 0) different++; if (i % 4 === 3 && candidate[i] > 0) alphaPixels++ }
      return { maxError, relativeError: error / Math.max(signal, 1e-20), different, alphaPixels }
    }
    const rows: any[] = []
    const variants: [string, ShaderMaterial][] = [
      ['baseline', baseline], ['productionLookup', candidate], ['baselineRepeat', baseline], ['productionRepeat', candidate]
    ]
    for (const [name, m] of variants) {
      render(m); const image = compare(read(output)); const timing = await measure(m)
      rows.push({ name, image, ...timing }); console.info('DUST', actorId, name, JSON.stringify({ image, summary: timing.summary }))
    }
    const diagnosticsSource = source.replace('if (alpha < 0.003) discard;', 'gl_FragColor = vec4(alpha, marched / steps, dt, 1.0); return;')
    render(make(diagnosticsSource)); const diagnostic = read(output)
    let covered = 0, discarded = 0, steps = 0, clumpsOff = 0, minAlpha = Infinity, maxAlpha = 0
    const alphaBins = Array(8).fill(0), edges = [.0001, .001, .003, .01, .03, .1, .3, Infinity]
    for (let i = 0; i < diagnostic.length; i += 4) if (diagnostic[i + 3] > 0) {
      covered++; const a = diagnostic[i]; if (a < .003) discarded++; steps += diagnostic[i + 1] * uniforms.uDustMaxSteps.value
      minAlpha = Math.min(minAlpha, a); maxAlpha = Math.max(maxAlpha, a); alphaBins[edges.findIndex(e => a < e)]++
      if (uniforms.uDustClumpStrength.value * Math.min(1, uniforms.uDustClumpScale.value / (2 * diagnostic[i + 2])) <= .001) clumpsOff++
    }
    if (!covered) throw new Error('Dust proxy empty')
    if (gl.getError() !== gl.NO_ERROR) throw new Error('Dust GPU error')
    if (rows.some(row => row.image.maxError > 1e-5 || row.image.alphaPixels !== rows[0].image.alphaPixels)) throw new Error('Production lookup image regression')
    return { actorId, width, height, snapshot, uniforms: values, defines: volume.material.defines, rows,
      creationMs, creation: stats(creationMs), lookupBytes: uniforms.uDustClumpGradients.value.image.data.byteLength,
      diagnostics: { covered, discarded, averageSteps: steps / covered, clumpsOff, minAlpha, maxAlpha, alphaBinEdges: edges, alphaBins } }
  } finally {
    renderer.render = draw
    baselineOwner.dispose()
    for (const m of materials) m.dispose(); for (const target of targets) target.dispose()
    blit.geometry.dispose(); blitMaterial.dispose()
    renderer.setRenderTarget(savedTarget); renderer.setClearColor(savedColor, savedAlpha); renderer.autoClear = savedAuto
    engine.start()
  }
}

