import { createServer } from 'vite'
import { chromium } from '@playwright/test'
import { writeFile } from 'node:fs/promises'
process.env.VITE_FS_DRIVER = 's3'
process.env.VITE_S3_URL = 'https://storage.yandexcloud.net'
process.env.VITE_FILE_BUCKET = 'textures'
process.env.VITE_SHOW_STATS_PANEL = 'false'
process.env.VITE_SKY_SOURCE = 'gaia'
const file = `benchmark-results/heavy-scenes/${process.env.REPORT_FILE || 'dust-lookup-production.json'}`
const report = { startedAt: new Date().toISOString(), rows: [], errors: [], warnings: [], assetFailures: [], outcome: 'failed' }
let server, browser
try {
  server = await createServer({ server: { host: '127.0.0.1', port: 8094, strictPort: true, hmr: false } }); await server.listen()
  browser = await chromium.launch({ channel: 'chrome', headless: true })
  const page = await browser.newPage({ viewport: { width: 1280, height: 720 }, deviceScaleFactor: 1 })
  page.on('pageerror', e => report.errors.push(e.stack || e.message))
  page.on('console', m => { if (m.type() === 'error') report.errors.push(m.text()); if (m.type() === 'warning') report.warnings.push(m.text()); if (m.text().startsWith('DUST')) console.log(m.text()) })
  page.on('response', r => { if (r.status() >= 400) report.assetFailures.push(`${r.status()} ${r.url()}`) })
  page.on('requestfailed', r => { if (!/ERR_ABORTED/.test(r.failure()?.errorText ?? '')) report.assetFailures.push(`${r.failure()?.errorText} ${r.url()}`) })
  await page.goto('http://127.0.0.1:8094/'); await page.getByRole('button', { name: /^Run / }).first().waitFor()
  for (const [id, actorId] of [[13, 135], [12, 127]]) {
    console.log('Starting', id)
    const selected = await page.evaluate(async id => {
      const probe = await import('/tests/browser/scenarioSoak.browser.ts')
      return Promise.race([probe.selectScenario(id), new Promise((_, reject) => setTimeout(() => reject(new Error('Scenario startup timed out')), 180000))])
    }, id)
    const view = await page.evaluate(async actorId => (await import('/benchmark-results/heavy-scenes/profile.browser.ts')).setView(actorId, 'belt'), actorId)
    await page.waitForTimeout(5000)
    const row = await page.evaluate(async actorId => (await import('/benchmark-results/heavy-scenes/dust-lookup.browser.ts')).diagnose(actorId), actorId)
    if (/SwiftShader|llvmpipe|software/i.test(row.snapshot.renderer)) throw new Error('Software renderer')
    report.rows.push({ selected, view, ...row }); await writeFile(file, JSON.stringify(report, null, 2))
    console.log(JSON.stringify(row.diagnostics))
    await page.screenshot({ path: `benchmark-results/heavy-scenes/dust-lookup-${id}.png` })
    await page.evaluate(async () => (await import('/tests/browser/scenarioSoak.browser.ts')).returnToMenu())
    if (report.errors.length || report.assetFailures.length) throw new Error('Browser or asset errors')
  }
  report.outcome = 'completed'
} catch (e) { report.failure = e.stack || e.message; console.error(e); process.exitCode = 1 }
finally { report.finishedAt = new Date().toISOString(); await writeFile(file, JSON.stringify(report, null, 2)); await browser?.close(); await server?.close() }
